//! Deterministic emitter for the committed `AEAD_CHUNKED_V2` corpus.
//!
//! The corpus is committed, not regenerated by the test suite: a format change
//! that moves a byte must fail `format_n_minus_1_reader_corpus` rather than
//! quietly rewrite the file it is checked against. This binary is how the
//! corpus is produced when a change is *intended*, and the diff it produces is
//! the reviewable evidence of that intent.
//!
//! Every input is fixed, so two runs on two machines emit identical bytes:
//!
//! ```text
//! cargo run -p academic-vault --features aead-objects --bin emit-object-corpus -- testdata/aead-chunked-v2
//! ```

use std::{env, fs, path::PathBuf, process::ExitCode};

use academic_domain::RetentionClass;
use academic_vault::object::{
    self, BASE_NONCE_BYTES, HEADER_BYTES, HEADER_LEN_FIELD, KEY_BYTES, StreamingPrefix, TAG_BYTES,
};

/// Fixed domain KEK. Synthetic, disposable, and committed alongside the object
/// it opens, because a corpus nobody can open proves nothing.
const DOMAIN_KEK: [u8; KEY_BYTES] = [
    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
    0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f,
];
/// Fixed per-object data-encryption key.
const DEK: [u8; KEY_BYTES] = [
    0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28, 0x29, 0x2a, 0x2b, 0x2c, 0x2d, 0x2e, 0x2f,
    0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f,
];
/// Fixed base nonce.
const BASE_NONCE: [u8; BASE_NONCE_BYTES] = [
    0x40, 0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4a, 0x4b, 0x4c, 0x4d, 0x4e, 0x4f,
    0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57,
];
const ARTIFACT_ID: [u8; 16] = [
    0x01, 0x90, 0x00, 0x00, 0x00, 0x00, 0x70, 0x00, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x01, 0x01,
];
const DOMAIN_ID: [u8; 16] = [
    0x01, 0x90, 0x00, 0x00, 0x00, 0x00, 0x70, 0x00, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x02, 0x01,
];
const PERMISSION_LINEAGE_ID: [u8; 16] = [
    0x01, 0x90, 0x00, 0x00, 0x00, 0x00, 0x70, 0x00, 0x80, 0x00, 0x00, 0x00, 0x00, 0x00, 0x03, 0x01,
];
/// Fixed base nonce of the zero-length vector, distinct from the one above so
/// the two committed objects never share chunk key material.
const EMPTY_BASE_NONCE: [u8; BASE_NONCE_BYTES] = [
    0x80, 0x81, 0x82, 0x83, 0x84, 0x85, 0x86, 0x87, 0x88, 0x89, 0x8a, 0x8b, 0x8c, 0x8d, 0x8e, 0x8f,
    0x90, 0x91, 0x92, 0x93, 0x94, 0x95, 0x96, 0x97,
];
const EMPTY_LOCATOR: [u8; 32] = [
    0xa0, 0xa1, 0xa2, 0xa3, 0xa4, 0xa5, 0xa6, 0xa7, 0xa8, 0xa9, 0xaa, 0xab, 0xac, 0xad, 0xae, 0xaf,
    0xb0, 0xb1, 0xb2, 0xb3, 0xb4, 0xb5, 0xb6, 0xb7, 0xb8, 0xb9, 0xba, 0xbb, 0xbc, 0xbd, 0xbe, 0xbf,
];
const LOCATOR: [u8; 32] = [
    0x60, 0x61, 0x62, 0x63, 0x64, 0x65, 0x66, 0x67, 0x68, 0x69, 0x6a, 0x6b, 0x6c, 0x6d, 0x6e, 0x6f,
    0x70, 0x71, 0x72, 0x73, 0x74, 0x75, 0x76, 0x77, 0x78, 0x79, 0x7a, 0x7b, 0x7c, 0x7d, 0x7e, 0x7f,
];
/// Small enough that the corpus stays reviewable, large enough that the object
/// is one whole chunk plus a partial one.
const CORPUS_CHUNK_SIZE: u32 = 32;
/// The exact plaintext both corpus objects hold.
const PLAINTEXT: &[u8] = b"synthetic academic artifact\nwith exact bytes\n";

fn main() -> ExitCode {
    match emit() {
        Ok(directory) => {
            println!(
                "wrote the AEAD_CHUNKED_V2 corpus to {}",
                directory.display()
            );
            ExitCode::SUCCESS
        }
        Err(message) => {
            eprintln!("corpus emission failed: {message}");
            ExitCode::FAILURE
        }
    }
}

fn emit() -> Result<PathBuf, String> {
    let directory = env::args_os()
        .nth(1)
        .map(PathBuf::from)
        .ok_or("usage: emit-object-corpus <directory>")?;
    fs::create_dir_all(&directory).map_err(|error| error.to_string())?;

    let prefix = StreamingPrefix::new(
        CORPUS_CHUNK_SIZE,
        ARTIFACT_ID,
        DOMAIN_ID,
        RetentionClass::UserManaged,
        PERMISSION_LINEAGE_ID,
        BASE_NONCE,
    );

    let chunk_size = CORPUS_CHUNK_SIZE as usize;
    let chunk_count = PLAINTEXT.len().div_ceil(chunk_size);
    let mut sealed = vec![0_u8; HEADER_BYTES];
    for index in 0..chunk_count {
        let start = index * chunk_size;
        let end = (start + chunk_size).min(PLAINTEXT.len());
        let mut chunk = PLAINTEXT[start..end].to_vec();
        object::seal_chunk(
            &DEK,
            &prefix,
            index as u64,
            index + 1 == chunk_count,
            &mut chunk,
        )
        .map_err(|error| error.to_string())?;
        sealed.extend_from_slice(&chunk);
    }

    let digest: [u8; 32] = academic_domain::ContentDigest::sha256(PLAINTEXT)
        .as_bytes()
        .to_owned();
    let header = prefix
        .seal_header(&DOMAIN_KEK, &DEK, LOCATOR, PLAINTEXT.len() as u64, digest)
        .map_err(|error| error.to_string())?;
    sealed[..HEADER_BYTES].copy_from_slice(&header);

    // A zero-length object is exactly one chunk, `len_0 = 0` and
    // `is_final = 1`. It is emitted as its own committed vector because it is
    // the case a writer that only counts `plaintext_len / chunk_size` gets
    // wrong, and the case a reader with no final chunk cannot authenticate.
    let empty_prefix = StreamingPrefix::new(
        CORPUS_CHUNK_SIZE,
        ARTIFACT_ID,
        DOMAIN_ID,
        RetentionClass::UserManaged,
        PERMISSION_LINEAGE_ID,
        EMPTY_BASE_NONCE,
    );
    let mut empty_chunk = Vec::new();
    object::seal_chunk(&DEK, &empty_prefix, 0, true, &mut empty_chunk)
        .map_err(|error| error.to_string())?;
    let empty_digest: [u8; 32] = academic_domain::ContentDigest::sha256(&[])
        .as_bytes()
        .to_owned();
    let empty_header = empty_prefix
        .seal_header(&DOMAIN_KEK, &DEK, EMPTY_LOCATOR, 0, empty_digest)
        .map_err(|error| error.to_string())?;
    let mut empty_sealed = empty_header.to_vec();
    empty_sealed.extend_from_slice(&empty_chunk);

    fs::write(directory.join("format-2.aobj"), &sealed).map_err(|error| error.to_string())?;
    fs::write(directory.join("format-2-empty.aobj"), &empty_sealed)
        .map_err(|error| error.to_string())?;
    fs::write(directory.join("format-1.obj"), PLAINTEXT).map_err(|error| error.to_string())?;

    let mut vectors = String::new();
    vectors.push_str("# Frozen AEAD_CHUNKED_V2 test vectors.\n");
    vectors.push_str("# Regenerate only with a deliberate format change:\n");
    vectors.push_str(
        "#   cargo run -p academic-vault --features aead-objects \\\n\
         #     --bin emit-object-corpus -- testdata/aead-chunked-v2\n",
    );
    vectors.push_str("# Every value is synthetic and disposable.\n");
    // `header_len` counts the header after the eight-byte
    // `ACOB | format_version | header_len` prefix: 208 bytes on disk, 200 in
    // the field. Two implementations split here without this line.
    vectors.push_str("# header_len excludes the 8-byte magic/version/len prefix.\n");
    vectors.push_str(&format!("header_len_field={HEADER_LEN_FIELD}\n"));
    vectors.push_str(&format!("header_total_bytes={HEADER_BYTES}\n"));
    vectors.push_str(&format!("chunk_size={CORPUS_CHUNK_SIZE}\n"));
    vectors.push_str("# chunk nonce = base_nonce XOR LE64(i+1) into base_nonce[16..24].\n");
    push_field(&mut vectors, "domain_kek", &DOMAIN_KEK);
    push_field(&mut vectors, "dek", &DEK);
    push_field(&mut vectors, "base_nonce", &BASE_NONCE);
    push_field(&mut vectors, "locator", &LOCATOR);
    push_field(&mut vectors, "plaintext", PLAINTEXT);
    push_field(&mut vectors, "plaintext_sha256", &digest);
    push_field(&mut vectors, "header", &header);
    push_field(&mut vectors, "streaming_prefix", &header[..86]);
    push_field(&mut vectors, "wrap_aad", &header[..128]);
    push_field(&mut vectors, "wrapped_dek", &header[128..HEADER_BYTES]);
    push_field(
        &mut vectors,
        "header_tag",
        &header[HEADER_BYTES - TAG_BYTES..],
    );
    push_field(&mut vectors, "sealed_object", &sealed);
    push_field(&mut vectors, "chunk_nonce_0", &prefix.chunk_nonce(0));
    push_field(&mut vectors, "chunk_nonce_1", &prefix.chunk_nonce(1));
    push_field(
        &mut vectors,
        "chunk_aad_0",
        &prefix.chunk_aad(0, CORPUS_CHUNK_SIZE, false),
    );
    push_field(
        &mut vectors,
        "chunk_aad_1",
        &prefix.chunk_aad(1, (PLAINTEXT.len() - chunk_size) as u32, true),
    );
    vectors.push_str("# Zero-length object: one chunk, len_0 = 0, is_final = 1.\n");
    push_field(&mut vectors, "empty_base_nonce", &EMPTY_BASE_NONCE);
    push_field(&mut vectors, "empty_locator", &EMPTY_LOCATOR);
    push_field(&mut vectors, "empty_plaintext_sha256", &empty_digest);
    push_field(&mut vectors, "empty_header", &empty_header);
    push_field(&mut vectors, "empty_sealed_object", &empty_sealed);
    push_field(
        &mut vectors,
        "empty_chunk_aad_0",
        &empty_prefix.chunk_aad(0, 0, true),
    );
    fs::write(directory.join("vectors.txt"), vectors).map_err(|error| error.to_string())?;
    Ok(directory)
}

fn push_field(out: &mut String, name: &str, bytes: &[u8]) {
    out.push_str(name);
    out.push('=');
    for byte in bytes {
        out.push(nibble(byte >> 4));
        out.push(nibble(byte & 0x0f));
    }
    out.push('\n');
}

fn nibble(value: u8) -> char {
    match value {
        0..=9 => char::from(b'0' + value),
        _ => char::from(b'a' + value - 10),
    }
}
